#!/usr/bin/env python3
# AI: below section was generated by an AI
"""
Recall a previously created light recipe BY NAME ("下次用创建好的名称继续调用").

Lookup order:
    1. a saved recipe file in recipes/ whose name matches (exact, then contains)
    2. a WLED preset on the device whose name matches (recalled by preset id)

Usage:
    python3 scripts/recall_recipe.py --list
    python3 scripts/recall_recipe.py "茉莉花盛开"
    python3 scripts/recall_recipe.py "sunset ocean" --preset-only

Output: JSON with {success, source, name, preset_id, ...}
"""
import json
import os
import sys
import time

SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))
SKILL_DIR = os.path.dirname(SCRIPT_DIR)
RECIPES_DIR = os.path.join(SKILL_DIR, "recipes")
sys.path.insert(0, SCRIPT_DIR)


def list_saved_recipes():
    out = []
    if not os.path.isdir(RECIPES_DIR):
        return out
    for fname in sorted(os.listdir(RECIPES_DIR)):
        if not fname.endswith(".json"):
            continue
        path = os.path.join(RECIPES_DIR, fname)
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            out.append({
                "file": fname,
                "path": path,
                "name": data.get("name", "unnamed"),
                "preset_id": data.get("preset_id"),
                "source_type": data.get("source_type", "image"),
                "created_at": data.get("created_at", ""),
            })
        except Exception:
            continue
    return out


def find_recipe_file(query):
    """Exact name match first, then case-insensitive substring match."""
    recipes = list_saved_recipes()
    q = (query or "").strip()
    if not q:
        return None
    for r in recipes:
        if r["name"] == q:
            return r
    ql = q.lower()
    for r in recipes:
        if ql in str(r["name"]).lower():
            return r
    return None


def find_preset_by_name(ip, query):
    """Find a WLED preset id whose name matches the query."""
    from apply_recipe import wled_request
    presets = wled_request(ip, "/presets.json", method="GET")
    if not isinstance(presets, dict):
        return None
    q = (query or "").strip().lower()
    for key, val in presets.items():
        if not isinstance(val, dict):
            continue
        if str(val.get("n", "")).strip().lower() == q:
            return int(key)
    for key, val in presets.items():
        if isinstance(val, dict) and q and q in str(val.get("n", "")).lower():
            return int(key)
    return None


def recall(query, preset_only=False, dry_run=False):
    from guard import require_write
    blocked = require_write(action="recall_recipe")
    if blocked:
        return blocked

    from apply_recipe import get_wled_ip, wled_request
    ip = get_wled_ip()
    if not ip:
        return {"success": False, "message": "WLED IP not configured. Run discover_wled.py first"}

    found = None if preset_only else find_recipe_file(query)

    if found:
        if dry_run:
            return {"success": True, "dry_run": True, "source": "recipe_file", **found}
        from import_recipe import import_recipe
        res = import_recipe(found["path"])
        res.update({"source": "recipe_file", "name": found["name"]})
        return res

    # Fallback: recall a device preset by name.
    preset_id = find_preset_by_name(ip, query)
    if preset_id is None:
        return {
            "success": False,
            "source": "none",
            "message": "找不到名称为 '{}' 的光配方（既无本地配方文件，也无同名 WLED 预设）".format(query),
            "available_recipes": [r["name"] for r in list_saved_recipes()],
        }
    if dry_run:
        return {"success": True, "dry_run": True, "source": "wled_preset",
                "name": query, "preset_id": preset_id}
    # Recalling a preset goes through the same handlePresets() path as saving it,
    # and that block is skipped while realtimeMode is set (wled.cpp:131). Clear
    # realtime / seize the override first, or "ps" is silently ignored.
    from apply_recipe import stop_udp_realtime
    realtime = stop_udp_realtime(ip)
    resp = wled_request(ip, "/json/state", method="POST", data={"ps": preset_id})
    time.sleep(0.6)
    state = wled_request(ip, "/json/state", method="GET")
    applied = state.get("ps") == preset_id if isinstance(state, dict) else None
    out = {
        "success": "error" not in (resp or {}),
        "source": "wled_preset",
        "name": query,
        "preset_id": preset_id,
        "ip": ip,
        "response": resp,
        "realtime": realtime,
        "verified": {"ps": state.get("ps") if isinstance(state, dict) else None,
                     "live": state.get("live") if isinstance(state, dict) else None,
                     "lor": state.get("lor") if isinstance(state, dict) else None},
        "message": "已通过 WLED 预设 {} 恢复光配方 '{}'".format(preset_id, query),
    }
    if applied is False:
        out["success"] = False
        out["message"] += " —— 但设备当前预设仍是 {}，可能被实时流占用".format(
            state.get("ps"))
    return out


def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__)
        sys.exit(0)

    if "--list" in sys.argv:
        recipes = list_saved_recipes()
        print(json.dumps({"success": True, "recipes": recipes, "count": len(recipes)},
                         indent=2, ensure_ascii=False))
        sys.exit(0)

    args = [a for a in sys.argv[1:] if not a.startswith("--")]
    if not args:
        print(json.dumps({"success": False, "message": "Usage: recall_recipe.py \"<name>\" [--preset-only]"}, ensure_ascii=False))
        sys.exit(1)

    result = recall(args[0], preset_only="--preset-only" in sys.argv, dry_run="--dry-run" in sys.argv)
    print(json.dumps(result, indent=2, ensure_ascii=False))
    sys.exit(0 if result.get("success") else 1)


if __name__ == "__main__":
    main()
# AI: end
